from flask import Flask, request, jsonify, g
import sqlite3
import os
import subprocess

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def get_current_user_id():
    """Extract user ID from session token - simplified auth"""
    token = request.headers.get('X-Session-Token', '')
    db = get_db()
    row = db.execute('SELECT user_id FROM sessions WHERE token = ?', (token,)).fetchone()
    if row:
        return row['user_id']
    return None

@app.route('/api/v1/users/<int:user_id>/profile', methods=['GET'])
def get_user_profile(user_id):
    """Fetch user profile by ID - no authorization check on resource ownership"""
    current_user = get_current_user_id()
    if current_user is None:
        return jsonify({'error': 'Unauthorized'}), 401

    # VULNERABILITY: No check that current_user == user_id
    # Any authenticated user can access any other user's profile
    db = get_db()
    profile = db.execute(
        'SELECT user_id, full_name, email, phone, ssn_last4, address, date_of_birth FROM profiles WHERE user_id = ?',
        (user_id,)
    ).fetchone()

    if profile is None:
        return jsonify({'error': 'Profile not found'}), 404

    return jsonify(dict(profile))

@app.route('/api/v1/users/<int:user_id>/documents', methods=['GET'])
def get_user_documents(user_id):
    """Fetch user documents - no authorization check"""
    current_user = get_current_user_id()
    if current_user is None:
        return jsonify({'error': 'Unauthorized'}), 401

    # VULNERABILITY: Same IDOR - any authenticated user can list another's documents
    db = get_db()
    docs = db.execute(
        'SELECT doc_id, filename, upload_date, doc_type FROM documents WHERE user_id = ?',
        (user_id,)
    ).fetchall()

    return jsonify({'documents': [dict(d) for d in docs]})

@app.route('/api/v1/users/<int:user_id>/documents/<int:doc_id>/download', methods=['GET'])
def download_document(user_id, doc_id):
    """Download a specific document - no authorization check"""
    current_user = get_current_user_id()
    if current_user is None:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    doc = db.execute(
        'SELECT filepath FROM documents WHERE user_id = ? AND doc_id = ?',
        (user_id, doc_id)
    ).fetchone()

    if doc is None:
        return jsonify({'error': 'Document not found'}), 404

    filepath = doc['filepath']
    # Read file from local storage
    try:
        with open(filepath, 'rb') as f:
            content = f.read()
        return content, 200, {'Content-Type': 'application/octet-stream'}
    except FileNotFoundError:
        return jsonify({'error': 'File missing'}), 500

@app.route('/api/v1/system/health', methods=['GET'])
def health_check():
    """System health endpoint - uses subprocess for disk check"""
    try:
        result = subprocess.run(
            ['df', '-h', '/var/lib/app'],
            capture_output=True, text=True, timeout=5
        )
        return jsonify({'status': 'healthy', 'disk': result.stdout})
    except Exception as e:
        return jsonify({'status': 'degraded', 'error': str(e)})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
